import csv
import io

def read_stock(text):
    totals = {}
    rejected = 0
    for row in csv.DictReader(io.StringIO(text)):
        item = (row.get("item") or "").strip()
        raw = (row.get("quantity") or "").strip()
        if not item or not raw or not all(char in "0123456789" for char in raw):
            rejected += 1
            continue
        totals[item] = totals.get(item, 0) + int(raw)
    return {"totals": totals, "rejected": rejected}
